                                                ULONG ulStartOffset,
                                                ULONG flags,
                                                LPCSTR caller)
{
     IPHeader *pIpHeader = (IPHeader *) RtlOffsetToPointer(pDataPages[0].Virtual, ulStartOffset);

     tTcpIpPacketParsingResult res = QualifyIpPacket(pIpHeader, ulDataLength);
     if (res.ipStatus == ppresIPV4)
