                msg.type = (typeof(msg.type))data.readInt32();
                size_t size = sizeof(msg.u);
                if (data.dataAvail() < size) {
                    err = BAD_VALUE;
                    break;
                }
                err = data.read(&msg.u, size);
                ALOGV("onTransact reading message %d, size %zu", msg.type, size);
                messages.push_back(msg);
 } while (err == OK);

 if (err == OK) {
                onMessages(messages);
 }

 return err;

 }

 default:
 return BBinder::onTransact(code, data, reply, flags);
 }
}

